#pragma once

#include "log.h"
#include "util.h"

#include <algorithm>
#include <cassert>
#include <chrono>
#include <compare>
#include <deque>
#include <functional>
#include <optional>
#include <stdexcept>
#include <unordered_map>

namespace ws {

template <typename Key>
class HeapTimer {
public:
    using Clock = std::chrono::steady_clock;
    using TimeOutCallback = std::function<void(const Key&)>;

    explicit HeapTimer(log::Logger::Ptr logger = log::RootLogger()) noexcept
        : logger_(std::move(logger)) {}

    void Push(const Key& key, Clock::duration expiration, TimeOutCallback callback) noexcept {
        assert(!Contain(key));
        const auto now = Clock::now();
        nodes_.emplace_back(Node{key, now + expiration, std::move(callback)});
        const auto idx = nodes_.size() - 1u;
        key_to_idx_[key] = idx;
        ShiftUp(idx);
    }

    void Push(const Key& key, Clock::time_point expiration, TimeOutCallback callback) noexcept {
        assert(!Contain(key));
        nodes_.emplace_back(Node{key, expiration, std::move(callback)});
        const auto idx = nodes_.size() - 1u;
        key_to_idx_[key] = idx;
        ShiftUp(idx);
    }

    void Adjust(const Key& key, Clock::duration expiration) {
        const auto now = Clock::now();
        Adjust(key, now + expiration);
    }

    void Adjust(const Key& key, Clock::time_point expiration) {
        const auto it = key_to_idx_.find(key);
        if (it == key_to_idx_.end()) {
            throw std::out_of_range("Key not found in HeapTimer");
        }
        const auto idx = it->second;
        auto& node = nodes_[idx];
        const auto old_expiration = node.expiration;
        node.expiration = expiration;
        if (expiration < old_expiration) {
            ShiftUp(idx);
        } else if (expiration > old_expiration) {
            ShiftDown(idx);
        }
    }

    void Tick() noexcept {
        while (!Empty()) {
            const auto& node = nodes_.front();
            if (!node.Expired()) break;
            try {
                node.callback(node.key);
            } catch (...) {
                logger_->error("Exception in timeout callback for key: {}", node.key);
            }
            Pop();
        }
    }

    bool Remove(const Key& key) noexcept {
        const auto it = key_to_idx_.find(key);
        if (it == key_to_idx_.end()) return false;
        const auto idx = it->second;
        RemoveByIndex(idx);
        return true;
    }

    Key Pop() noexcept {
        assert(!Empty());
        const auto key = nodes_.front().key;
        RemoveByIndex(0u);
        return key;
    }

    void Clear() noexcept {
        nodes_.clear();
        key_to_idx_.clear();
    }

    bool Contain(const Key& key) const noexcept {
        return key_to_idx_.find(key) != key_to_idx_.end();
    }

    bool Empty() const noexcept {
        return nodes_.empty();
    }

    std::size_t Size() const noexcept {
        return nodes_.size();
    }

    Clock::duration ToNextTick() noexcept {
        if (Empty()) return Clock::duration::max();
        const auto now = Clock::now();
        const auto next = nodes_.front().expiration;
        return std::max(Clock::duration::zero(), next - now);
    }

private:
    struct Node {
        Key key;
        Clock::time_point expiration;
        TimeOutCallback callback;

        bool Expired() const noexcept {
            return Clock::now() >= expiration;
        }

        void Swap(Node& other) noexcept {
            std::swap(key, other.key);
            std::swap(expiration, other.expiration);
            std::swap(callback, other.callback);
        }

        friend std::weak_ordering operator<=>(const Node& lhs, const Node& rhs) noexcept {
            return lhs.expiration <=> rhs.expiration;
        }
    };

    void ShiftUp(std::size_t idx) noexcept {
        while (idx > 0u) {
            const auto parent = (idx - 1u) / 2u;
            if (!(nodes_[idx] < nodes_[parent])) break;
            nodes_[idx].Swap(nodes_[parent]);
            key_to_idx_[nodes_[idx].key] = idx;
            key_to_idx_[nodes_[parent].key] = parent;
            idx = parent;
        }
    }

    void ShiftDown(std::size_t idx) noexcept {
        const auto last = nodes_.size() - 1u;
        while (true) {
            std::size_t child = 2u * idx + 1u;
            if (child > last) break;
            if (child + 1u <= last && nodes_[child] > nodes_[child + 1u]) {
                ++child;
            }
            if (!(nodes_[child] < nodes_[idx])) break;
            nodes_[idx].Swap(nodes_[child]);
            key_to_idx_[nodes_[idx].key] = idx;
            key_to_idx_[nodes_[child].key] = child;
            idx = child;
        }
    }

    void RemoveByIndex(std::size_t idx) noexcept {
        if (idx == nodes_.size() - 1u) {
            nodes_.pop_back();
            key_to_idx_.erase(nodes_[idx].key);
            return;
        }
        nodes_[idx].Swap(nodes_.back());
        key_to_idx_[nodes_[idx].key] = idx;
        key_to_idx_[nodes_.back().key] = nodes_.size() - 1u;
        nodes_.pop_back();
        if (idx < nodes_.size()) {
            ShiftDown(idx);
        }
    }

    log::Logger::Ptr logger_;
    std::unordered_map<Key, std::size_t> key_to_idx_;
    std::deque<Node> nodes_;
};

} // namespace ws
